{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 Bucket Public Access Block: ACLs not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The resource does not explicitly set 'block_public_acls' to true, leaving the bucket vulnerable to public access via ACLs."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "S3 Bucket Public Access Block: Policy not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The resource does not explicitly set 'block_public_policy' to true, allowing potentially unsafe public bucket policies to be applied."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "S3 Bucket Public Access Block: Ignore public ACLs not enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The resource does not explicitly set 'ignore_public_acls' to true, meaning existing or new public ACLs are not ignored."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "S3 Bucket Public Access Block: Restrict public buckets disabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "HIGH",
      "explanation": "'restrict_public_buckets' is explicitly set to false, which allows public bucket policies and ACLs to grant public access to the S3 bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket                  = aws_s3_bucket.api_docs.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Enabled all four public access block settings (block_public_acls, block_public_policy, ignore_public_acls) and changed restrict_public_buckets from false to true to prevent unauthorized public access to the S3 bucket."
}
